//! PublicIds: the only ids that leave a service (spec 3.1). Generated by the app as ULIDs.
//!
//! Parsing is deliberately loose (26 chars of [0-9A-Z]) rather than strict ULID: the built-in tutor
//! templates seeded in schema-v5-ai.sql use ids like `01JBUILTIN...` that contain letters Crockford
//! base32 excludes. See OPEN-QUESTIONS.md.

use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(try_from = "String", into = "String")]
pub struct PublicId(String);

#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
#[error("not a valid id")]
pub struct InvalidId;

impl PublicId {
    pub fn parse(s: &str) -> Result<Self, InvalidId> {
        let ok = s.len() == 26 && s.bytes().all(|b| b.is_ascii_digit() || b.is_ascii_uppercase());
        if ok { Ok(Self(s.to_owned())) } else { Err(InvalidId) }
    }

    /// For values that come out of our own database or id generator.
    pub fn from_trusted(s: String) -> Self {
        Self(s)
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl TryFrom<String> for PublicId {
    type Error = InvalidId;
    fn try_from(s: String) -> Result<Self, Self::Error> {
        Self::parse(&s)
    }
}

impl From<PublicId> for String {
    fn from(id: PublicId) -> Self {
        id.0
    }
}

impl std::fmt::Display for PublicId {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn accepts_ulids_and_builtin_ids() {
        assert!(PublicId::parse("01JC9Z8Q4R5T6Y7U8I9O0PASDF").is_ok());
        assert!(PublicId::parse("01JBUILTIN0000000000000001").is_ok());
    }

    #[test]
    fn rejects_wrong_length_lowercase_and_symbols() {
        assert!(PublicId::parse("01JC9Z8Q4R5T6Y7U8I9O0PASD").is_err());
        assert!(PublicId::parse("01jc9z8q4r5t6y7u8i9o0pasdf").is_err());
        assert!(PublicId::parse("01JC9Z8Q4R5T6Y7U8I9O0PAS-F").is_err());
        assert!(PublicId::parse("42").is_err());
    }
}
